def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_o = opp[-1]
    last_m = me[-1]
    opp_def = n - opp.count('C')

    # Endgame: exploit in final rounds when safe.
    if n >= 99:
        return 'D'
    if n >= 97:
        recent = opp[-5:]
        if recent.count('D') >= 2:
            return 'D'
        if opp_def == 0:
            return 'C'
        return 'D'

    # Never cooperate when partner is a pure defector.
    if opp_def == n and n >= 4:
        return 'D'

    # Perfect cooperation: keep cooperating, exploit only rarely and late.
    if opp_def == 0:
        if n >= 92:
            return 'D'
        if n >= 60 and n % 10 == 9:
            return 'D'
        return 'C'

    # Detect sustained high defection.
    if n >= 12:
        ratio = opp_def / n
    else:
        ratio = 0.0

    # Recent windows
    w = 12 if n >= 12 else n
    recent = opp[-w:]
    recent_c = recent.count('C')
    recent_d = w - recent_c

    # Sustained heavy defection: punish, probe rarely.
    if n >= 10 and ratio > 0.5:
        if n % 11 == 0:
            return 'C'
        return 'D'

    if n >= 10 and recent_d >= w - 2:
        # almost all recent defections
        if n % 9 == 0:
            return 'C'
        return 'D'

    # A short punishment for recent defections, then forgive.
    # Detect a single disruption in otherwise cooperative play.
    if last_o == 'D':
        # How many defections in last 4?
        tail4 = opp[-4:] if n >= 4 else opp
        d4 = tail4.count('D')
        # If it's a blip (mostly cooperation before), forgive quickly.
        if n >= 6:
            prev = opp[-8:-1] if n >= 8 else opp[:-1]
            if prev and prev.count('D') <= 1:
                # blip: retaliate once, then return to C
                if last_m == 'D':
                    return 'C'
                return 'D'
        if d4 >= 3:
            return 'D'
        if last_m == 'D':
            # alternating retaliation risk; restore cooperation
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we defected last round, restore cooperation to keep them nice.
    if last_m == 'D':
        # If we're being exploited (opp defected despite our D), keep D
        if n >= 4 and opp[-1] == 'D':
            return 'D'
        return 'C'

    # Healthy mutual cooperation: keep it.
    if recent_c >= w - 1 and ratio <= 0.2:
        return 'C'

    # Moderate defection rate - mix of cooperation with defensive retaliation.
    if ratio > 0.3:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Low but nonzero defections: probe occasionally for exploitation.
    if ratio > 0.1:
        if recent_d >= 2:
            return 'D'
        if n > 20 and n % 13 == 12:
            return 'D'
        return 'C'

    # Very cooperative partner with rare isolated defections.
    if n > 25 and n % 17 == 16:
        return 'D'
    return 'C'
